          },
          evidence: [
            { id: "cutover_time", label: "切换生效时间（HH:MM）", placeholder: "如 15:18", pattern: "^([01]?\\d|2[0-3]):[0-5]\\d$", patternHint: "格式：HH:MM" },
            { id: "change_no", label: "变更单号", placeholder: "如 CHG-2026-0916-07" }
          ]
        },
        {
          id: "s10",
          kind: "normal",
          title: "验证新主写入与复制",
          summary: "确认新主库真实承载写入，且新的从库链路正常追平。",
          actions: [
            "执行写入探针（写测试表并读回比对）",
            "检查从库复制延迟",
            "确认备份任务已指向新主库"
          ],
