            "备份任务已指向新主库"
          ],
          evidence: [
            { id: "probe_ms", label: "探针延迟（ms）", placeholder: "如 12", pattern: "^\\d+$", patternHint: "纯数字" }
          ]
        }
      ]
    },
    {
      id: "phase-close",
      name: "阶段四 · 验证与收尾",
      steps: [
        {
          id: "s11",
          kind: "normal",
          title: "业务冒烟验证",
          summary: "用真实业务链路验证切换结果，避免「数据库正常但业务不可用」。",
          actions: [
            "执行核心链路冒烟用例",
            "观察支付 / 下单等关键链路错误率",
            "与客服侧确认无相关投诉上升"
          ],
          checks: [
            "核心链路冒烟用例全部通过",
            "关键链路错误率恢复正常",
            "客服侧无相关投诉上升"
          ],
          evidence: [
            { id: "smoke_ticket", label: "冒烟执行单号", placeholder: "如 ST-0916-114" }
          ]
        },
        {
          id: "s12",
          kind: "normal",
          title: "观察期监控",
          summary: "切换后 15 分钟观察窗：盯紧延迟、错误率与复制健康度。",
          actions: [
            "保持观察窗内高频巡检",
            "对比切换前后 P99 延迟曲线"
          ],
          checks: [
            "观察窗内无 P0 / P1 告警",
            "复制延迟持续 < 1s",
            "应用 P99 延迟回落至基线"
          ],
          evidence: [
            { id: "observe_start", label: "观察窗开始时间（HH:MM）", placeholder: "如 15:26", pattern: "^([01]?\\d|2[0-3]):[0-5]\\d$", patternHint: "格式：HH:MM" }
          ]
        },
        {
          id: "s13",
          kind: "decision",
          title: "复盘与旧主处置决策",
