          decision: {
            options: [
              {
                id: "rebuild",
                label: "重建旧主为新从库（推荐）",
                detail: "以 s6 快照将旧主库重建为新的从库，恢复一主一从冗余，预计 2 小时内完成。",
                outcome: "完成后冗余恢复，流程正常收尾",
                aborts: false
              },
              {
                id: "standby",
                label: "旧主降级待重建",
                detail: "资源受限时先将旧主下线隔离，挂重建工单；期间单副本运行并提升告警级别。",
                outcome: "单副本运行期需提升告警级别，流程正常收尾",
                aborts: false
              }
            ]
          },
          checks: [
            "复盘会议已排期（24 小时内）",
