  assert("恢复触发：s8 回退为当前待执行", afterRec.current.includes("提升从库"), afterRec.current);
  await shot("08-recovery-deviation.png");
  // 重新走 s8
  await fillStep(6); await confirmIrreversible("PROMOTE");

