  assert("零失误完成：最终判定为零偏差完成", final.verdict.includes("零失误走完全程"), final.verdict);
  assert("零失误完成：全程零偏差徽标", final.badge === "零偏差", final.badge);
  await shot("12-completion-zero-deviation.png");

