import { spawn } from "node:child_process";
import { resolve } from "node:path";

const proc = spawn("C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe", [
  "--headless=new", "--remote-debugging-port=9344", "--remote-allow-origins=*",
  "--user-data-dir=" + resolve(".chrome-tmp"), "--no-first-run", "--disable-gpu", "--window-size=1440,900", "about:blank"
], { stdio: "ignore" });

let wsUrl;
for (let i = 0; i < 60; i++) {
  try {
    const r = await fetch("http://127.0.0.1:9344/json/list");
    const l = await r.json();
    const p = l.find((t) => t.type === "page");
    if (p) { wsUrl = p.webSocketDebuggerUrl; break; }
  } catch {}
  await new Promise((r) => setTimeout(r, 300));
}
const ws = new WebSocket(wsUrl);
await new Promise((r) => (ws.onopen = r));
let id = 0;
const pending = new Map();
ws.onmessage = (m) => {
  const d = JSON.parse(m.data);
  if (d.id && pending.has(d.id)) { pending.get(d.id)(d); pending.delete(d.id); }
};
const send = (method, params = {}) => new Promise((res) => { const mid = ++id; pending.set(mid, res); ws.send(JSON.stringify({ id: mid, method, params })); });
const ev = async (expr) => {
  const r = await send("Runtime.evaluate", { expression: expr, returnByValue: true });
  if (r.result?.subtype === "error" || r.exceptionDetails) console.log("EVAL-ERR", JSON.stringify(r.exceptionDetails || r.result?.description));
  return r.result?.value;
};

await send("Page.enable");
await send("Runtime.enable");
const url = "file:///" + resolve("index.html").replace(/\\/g, "/");
await send("Page.navigate", { url });
await new Promise((r) => setTimeout(r, 1200));

const EV = { alarm_id: "A", commander: "B", freeze_time: "14:30", notice_channel: "c", replica_lag: "180", decision_reason: "r", snapshot_id: "s", gtid: "g" };
console.log("after 6 steps:", await ev(`(() => {
  const vals = ${JSON.stringify(EV)};
  const stepOnce = (dec) => {
    document.querySelectorAll('#work-body .check-item input[data-field="check"]').forEach(cb => { if (!cb.checked) { cb.checked = true; cb.dispatchEvent(new Event('change',{bubbles:true})); } });
    document.querySelectorAll('#work-body [data-field="ev"]').forEach(el => { el.value = vals[el.getAttribute('data-fid')] || 'x'; el.dispatchEvent(new Event('input',{bubbles:true})); });
    if (dec) { const rr = document.querySelector('#work-body input[data-field="decision"][data-oid="'+dec+'"]'); if (rr) { rr.checked = true; rr.dispatchEvent(new Event('change',{bubbles:true})); } }
    document.querySelector('#work-body .action-bar button').click();
  };
  stepOnce(); stepOnce(); stepOnce(); stepOnce(); stepOnce('failover'); stepOnce();
  return document.querySelector('#work-body h1').textContent;
})()`));

console.log("btn info:", await ev(`(() => { const btn = document.querySelector('#work-body .action-bar button'); const info = { txt: btn.textContent, dis: btn.disabled, act: btn.getAttribute('data-act') }; btn.click(); return info; })()`));
await new Promise((r) => setTimeout(r, 200));
console.log("modal state:", await ev(`(() => ({ hidden: document.getElementById('modal-overlay').hidden, modalLen: document.getElementById('modal').innerHTML.length, h2: (document.querySelector('#modal h2')||{}).textContent }))()`));

ws.close();
proc.kill();

