  assert("首屏就绪：无加载态", ready.loadState === "complete" && ready.progress === "0 / 13 步", ready.progress);
  console.log("TIMING load->probe " + (Date.now() - t0) + "ms");
  await shot("01-ready-first-screen.png");

  /* ========== 场景 B：门禁拦截 ========== */
