    } else {
      btn = '<button type="button" class="btn btn-primary" data-act="advance" data-idx="' + i + '"' + (g.ok ? "" : " disabled") + ">完成本步并放行</button>";
    }
    return '<div class="action-bar" data-action-bar="' + i + '">' + hint + btn + "</div>";
