    if (state.outcome === "completed")
      return { cls: "verdict-deviation", icon: "⚠️", title: "完成，但存在 " + dev + " 次偏差", text: "流程已走完全程，但过程中触发了恢复路径。偏差明细已记入审计，请在复盘会议中逐条归因。" };
